using namespace std; 

struct Student { // struct 
    string name; // stud name
    string gender; // gender
    string program; // program 
    int age; // age
};

static inline string trim(const string& s) { // function para tanggalin ang whitespace sa magkabilang dulo ng string
    size_t start = s.find_first_not_of(" \t\r\n"); // hanapin ang last non whitespace character
    if (start == string::npos) return ""; // if emptty return the empty string
    size_t end = s.find_last_not_of(" \t\r\n"); // hanapin ang last non whitespace character (ulit-ulit haha)
    return s.substr(start, end - start + 1); // return the trimmed substring
}

bool parseStudentLine(const string& line, Student& out) { // parse the CSV line through the Student struct
    stringstream ss(line); // gamitin ang stringstream para ma split ang line
    string name, gender, program, ageStr; // temporary variables for each feilds
    if (!getline(ss, name, ',')) return false; 
    if (!getline(ss, gender, ',')) return false; 
    if (!getline(ss, program, ',')) return false; 
    if (!getline(ss, ageStr)) return false; 
    out.name = trim(name); // trim and assign the name sa output struct
    out.gender = trim(gender); // trim and assign the gender
    out.program = trim(program); // trim and assign the program
    try {
        out.age = stoi(trim(ageStr)); // i-convert ang age string sa integer at i assign
    } catch (...) {
        return false; // kung may error sa conversion, return false
    }
    return true; 
}

string studentToLine(const Student& s) { // gawing CSV line ang isang Student struct
    stringstream ss; // use stringstream para buuhin ang line
    ss << s.name << "," << s.gender << "," << s.program << "," << s.age; // ilagay ang fields na pinaghiwalay ng comma
    return ss.str(); // ibalik ang nabuo na CSV line
}

bool loadFromFile(const string& filename, vector<Student>& students) { // load lahat ng content from the file to the vector
    ifstream fin(filename); // buksan ang file para basahin
    if (!fin) { // if hindi mabuksan or wala pang file
        students.clear(); // dapat empty ang vector
        return true; 
    }
    string line; 
    students.clear(); // clear muna ang vector bago mag load
    while (getline(fin, line)) { // basahin ang bawat linya ng file
        if (trim(line).empty()) continue; // laktawan ang blank lines
        Student s; // temporary Student 
        if (parseStudentLine(line, s)) { // testingin i-parse ang linya
            students.push_back(s); // kung successful edi idagdag sa vector
        }
    }
    return true; 
}

bool saveToFile(const string& filename, const vector<Student>& students) { // overwrite
    ofstream fout(filename, ios::trunc); // buksan ang file at i-truncate para i overwrite
    if (!fout) return false; // kung hindi mabuksan ang file false
    for (const auto& s : students) { // i-iterate ang bawat student sa vector
        fout << studentToLine(s) << '\n'; // isulat bilang CSV line at newline
    }
    return true; 
}

