void searchStudent(const vector<Student>& students) { // searching function
    if (students.empty()) { // kung walang laman ang list
        cout << "Wala pang students para i-search.\n"; 
        pauseConsole(); // pause 
        return; 
    }
    cout << "Enter search term (searches name): "; 
    string term; // variable 
    getline(cin, term); // basahin ang term
    string lowerTerm = term; // lowercase copy for case insensitive search
    transform(lowerTerm.begin(), lowerTerm.end(), lowerTerm.begin(), ::tolower); // convert to lowercase

    bool found = false;
    for (size_t i = 0; i < students.size(); ++i) { // iterate sa lahat ng students
        string lowerName = students[i].name; 
        transform(lowerName.begin(), lowerName.end(), lowerName.begin(), ::tolower); // convert name to lowercase
        if (lowerName.find(lowerTerm) != string::npos) { // kung may match
            displayStudent(students[i], static_cast<int>(i + 1)); // ipakita ang matching student
            found = true; // set the flag to true to stop searching
        }
    }
    if (!found) cout << "Wala akong nakita na match. Try ibang term.\n";
    pauseConsole(); 
}

