string getDate() { // get the current date
    // Get current time
    time_t now = time(0); // current epoch time
    tm *ltm = localtime(&now); // convert to local time struct

    // Format: YYYY-MM-DD
    ostringstream oss;
    oss << 1900 + ltm->tm_year << "-" // year
        << std::setw(2) << std::setfill('0') << 1 + ltm->tm_mon << "-" // month (1-based)
        << std::setw(2) << std::setfill('0') << ltm->tm_mday; // day

    return oss.str(); // return formatted date string
}

