void transactions(Users* user){
    clearConsole(); // clear screen for transactions view
    ifstream fin;
    fin.open("transactions.txt"); // open transactions file
    if (!fin){
        cerr << "Cannot open transaction file"; // error if file missing
        return; // abort
    }

    string line; // buffer for each transaction line

    cout << "TRANSACTIONS\n\n"; // header
    while (getline(fin, line)){ // read each line
        stringstream ss(line); // parse line into fields

        string username, type, amountStr, date; // parsed fields
        double amount = 0.0; // parsed amount

        // robust parsing: read amount as string using delimiter then convert
        if (!getline(ss, username, '|')) continue; // read username
        if (!getline(ss, type, '|')) continue; // read type
        if (!getline(ss, amountStr, '|')) continue; // read amount as string
        if (!getline(ss, date)) date = ""; // read remaining date

        try {
            amount = stod(amountStr);
        } catch (...) {
            // malformed amount, skip this line
            continue;
        }

        if (username == user->userName){ // show only current user's transactions
            cout << type << " | "
                 << fixed << setprecision(2) << amount << " | "
                 << date << " | " << endl; // print transaction details
        }
    }
    fin.close(); // close file
    system("pause"); // wait for user

}

